export class AnalyticsClient {
  readonly #device: Device

  constructor(device: Device) {
    this.#device = device
  }

  /**
   * @param configurationToken - The `ConfigurationToken` of every request
   * @returns The operations that take a `ConfigurationToken`, without it in the request
   */
  forConfiguration(configurationToken: string): AnalyticsConfigurationClient {
    return new AnalyticsConfigurationClient(this.#device, configurationToken)
  }

  /**
   * Returns the capabilities of the analytics service. The result is returned in a typed answer.
   *
   * @param request - The `GetServiceCapabilities` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetServiceCapabilitiesResponse`
   */
  getServiceCapabilities(
    request?: GetServiceCapabilitiesRequest,
    options?: CallOptions
  ): Promise<GetServiceCapabilitiesResponse> {
    return this.#device.call(GetServiceCapabilities, request, options)
  }

  /**
   * List all analytics modules that are supported by the given VideoAnalyticsConfiguration.
   *
   * @param request - The `GetSupportedAnalyticsModules` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetSupportedAnalyticsModulesResponse`
   */
  getSupportedAnalyticsModules(
    request: GetSupportedAnalyticsModulesRequest,
    options?: CallOptions
  ): Promise<GetSupportedAnalyticsModulesResponse> {
    return this.#device.call(GetSupportedAnalyticsModules, request, options)
  }

  /**
   * List the currently assigned set of analytics modules of a VideoAnalyticsConfiguration.
   *
   * @param request - The `GetAnalyticsModules` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetAnalyticsModulesResponse`
   */
  getAnalyticsModules(
    request: GetAnalyticsModulesRequest,
    options?: CallOptions
  ): Promise<GetAnalyticsModulesResponse> {
    return this.#device.call(GetAnalyticsModules, request, options)
  }

  /**
   * Add one or more analytics modules to an existing VideoAnalyticsConfiguration. The available
   * supported types can be retrieved via GetSupportedAnalyticsModules, where the Name of the supported
   * AnalyticsModules correspond to the type of an AnalyticsModule instance. Pass unique module names
   * which can be later used as reference. The Parameters of the analytics module must match those of the
   * corresponding AnalyticsModuleDescription. Although this method is mandatory a device implementation
   * may not support adding modules. Instead it can provide a fixed set of predefined configurations via
   * the media service functions GetCompatibleVideoAnalyticsConfigurations and
   * GetAnalyticsConfigurations. The device shall ensure that a corresponding analytics engine starts
   * operation when a client subscribes directly or indirectly for events produced by the analytics or
   * rule engine or when a client requests the corresponding scene description stream. An analytics
   * module must be attached to a Video source using the media profiles before it can be used. In case
   * differing analytics configurations are attached to the same profile it is undefined which of the
   * analytics module configuration becomes active if no stream is activated or multiple streams with
   * different profiles are activated at the same time.
   *
   * @param request - The `CreateAnalyticsModules` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `CreateAnalyticsModulesResponse`
   */
  createAnalyticsModules(
    request: CreateAnalyticsModulesRequest,
    options?: CallOptions
  ): Promise<CreateAnalyticsModulesResponse> {
    return this.#device.call(CreateAnalyticsModules, request, options)
  }

  /**
   * Modify the settings of one or more analytics modules of a VideoAnalyticsConfiguration. The modules
   * are referenced by their names. It is allowed to pass only a subset to be modified.
   *
   * @param request - The `ModifyAnalyticsModules` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `ModifyAnalyticsModulesResponse`
   */
  modifyAnalyticsModules(
    request: ModifyAnalyticsModulesRequest,
    options?: CallOptions
  ): Promise<ModifyAnalyticsModulesResponse> {
    return this.#device.call(ModifyAnalyticsModules, request, options)
  }

  /**
   * Remove one or more analytics modules from a VideoAnalyticsConfiguration referenced by their names.
   *
   * @param request - The `DeleteAnalyticsModules` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `DeleteAnalyticsModulesResponse`
   */
  deleteAnalyticsModules(
    request: DeleteAnalyticsModulesRequest,
    options?: CallOptions
  ): Promise<DeleteAnalyticsModulesResponse> {
    return this.#device.call(DeleteAnalyticsModules, request, options)
  }

  /**
   * Return the options for the supported analytics modules that specify an Option attribute.
   *
   * @param request - The `GetAnalyticsModuleOptions` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetAnalyticsModuleOptionsResponse`
   */
  getAnalyticsModuleOptions(
    request: GetAnalyticsModuleOptionsRequest,
    options?: CallOptions
  ): Promise<GetAnalyticsModuleOptionsResponse> {
    return this.#device.call(GetAnalyticsModuleOptions, request, options)
  }

  /**
   * This method provides a computer readable description of the metadata that the selected analytics
   * modules can generate. The type parameter allows to select a single analytics module. By default the
   * output shall relate to all analytics modules that exist in the device. The response shall provide a
   * sample XML frame. The sample frame shall include all potentially generated elements by the selected
   * analytics modules. Note that this e.g. does not need to include all possible class type
   * enumerations.
   *
   * @param request - The `GetSupportedMetadata` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetSupportedMetadataResponse`
   */
  getSupportedMetadata(
    request?: GetSupportedMetadataRequest,
    options?: CallOptions
  ): Promise<GetSupportedMetadataResponse> {
    return this.#device.call(GetSupportedMetadata, request, options)
  }

  /**
   * List all rules that are supported by the given VideoAnalyticsConfiguration.
   *
   * @param request - The `GetSupportedRules` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetSupportedRulesResponse`
   */
  getSupportedRules(request: GetSupportedRulesRequest, options?: CallOptions): Promise<GetSupportedRulesResponse> {
    return this.#device.call(GetSupportedRules, request, options)
  }

  /**
   * List the currently assigned set of rules of a VideoAnalyticsConfiguration.
   *
   * @param request - The `GetRules` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetRulesResponse`
   */
  getRules(request: GetRulesRequest, options?: CallOptions): Promise<GetRulesResponse> {
    return this.#device.call(GetRules, request, options)
  }

  /**
   * Add one or more rules to an existing VideoAnalyticsConfiguration. The available supported types can
   * be retrieved via GetSupportedRules, where the Name of the supported rule correspond to the type of
   * an rule instance. Pass unique module names which can be later used as reference. The Parameters of
   * the rules must match those of the corresponding description. Although this method is mandatory a
   * device implementation must not support adding rules. Instead it can provide a fixed set of
   * predefined configurations via the media service function GetCompatibleVideoAnalyticsConfigurations.
   *
   * @param request - The `CreateRules` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `CreateRulesResponse`
   */
  createRules(request: CreateRulesRequest, options?: CallOptions): Promise<CreateRulesResponse> {
    return this.#device.call(CreateRules, request, options)
  }

  /**
   * Modify one or more rules of a VideoAnalyticsConfiguration. The rules are referenced by their names.
   *
   * @param request - The `ModifyRules` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `ModifyRulesResponse`
   */
  modifyRules(request: ModifyRulesRequest, options?: CallOptions): Promise<ModifyRulesResponse> {
    return this.#device.call(ModifyRules, request, options)
  }

  /**
   * Remove one or more rules from a VideoAnalyticsConfiguration.
   *
   * @param request - The `DeleteRules` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `DeleteRulesResponse`
   */
  deleteRules(request: DeleteRulesRequest, options?: CallOptions): Promise<DeleteRulesResponse> {
    return this.#device.call(DeleteRules, request, options)
  }

  /**
   * Return the options for the supported rules that specify an Option attribute.
   *
   * @param request - The `GetRuleOptions` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetRuleOptionsResponse`
   */
  getRuleOptions(request: GetRuleOptionsRequest, options?: CallOptions): Promise<GetRuleOptionsResponse> {
    return this.#device.call(GetRuleOptions, request, options)
  }
}

